INSERT INTO question_bank (question_id, section_code, category_code, level_tag, text, option_a, option_b, option_c, option_d, score_a, score_b, score_c, score_d, active) VALUES
  ($qb$S01C01Q01$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$When your organisation faces a major strategic decision, the process typically looks like:$qb$, $qb$Structured — data reviewed, options mapped, implications stress-tested, decision documented with rationale$qb$, $qb$Discussed in leadership meetings but largely driven by the most senior person's instinct$qb$, $qb$Decided quickly at the top with limited structured analysis — speed is prioritised over rigour$qb$, $qb$Unclear — major decisions happen without a visible or consistent process$qb$, 5, 3, 2, 1, true),
  ($qb$S01C01Q02$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$When two equally valid strategic options exist, leadership in your organisation typically:$qb$, $qb$Runs structured scenario analysis — risks, costs, and outcomes of each option are formally compared before deciding$qb$, $qb$Debates the options in a meeting and reaches consensus, though the analysis is mostly verbal$qb$, $qb$Defers to the most senior leader's preference without formal comparison$qb$, $qb$Avoids the decision — ambiguous choices are frequently postponed until the situation forces a call$qb$, 5, 3, 2, 1, true),
  ($qb$S01C01Q03$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$Decisions made in leadership meetings in your organisation are:$qb$, $qb$Documented with rationale, owner, and deadline — traceable and reviewable$qb$, $qb$Communicated verbally but rarely documented formally$qb$, $qb$Sometimes recorded in minutes but rarely followed up on$qb$, $qb$Not systematically captured — what was decided is often disputed later$qb$, 5, 3, 2, 1, true),
  ($qb$S01C01Q04$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$MM$qb$, $qb$When department heads receive a leadership decision they believe is flawed, the typical outcome is:$qb$, $qb$They raise concerns through a defined escalation channel and leadership genuinely reconsiders when the case is strong$qb$, $qb$They raise it informally with a trusted senior leader but rarely through formal channels$qb$, $qb$They comply without raising concerns — pushing back is not culturally safe$qb$, $qb$They privately resist or delay execution while appearing compliant$qb$, 5, 3, 2, 1, true),
  ($qb$S01C01Q05$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$Your organisation's leadership uses external benchmarks (industry data, competitor analysis, global best practice) in decision-making:$qb$, $qb$Regularly — external data is a standard input in major decisions$qb$, $qb$Occasionally — used when someone happens to surface relevant data$qb$, $qb$Rarely — leadership trusts internal experience over external benchmarks$qb$, $qb$Almost never — decisions are made entirely from internal perspective$qb$, 5, 3, 2, 1, true),
  ($qb$S01C01Q06$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$L+MM+E$qb$, $qb$In your organisation, the time between identifying a problem and making a decision to address it is:$qb$, $qb$Fast — most operational problems are decided within days; strategic ones within weeks$qb$, $qb$Moderate — decisions take longer than they should but eventually get made$qb$, $qb$Slow — decisions are frequently deferred, re-discussed, or waiting for approval$qb$, $qb$Very slow — decision paralysis is a recognised and recurring organisational problem$qb$, 5, 3, 2, 1, true),
  ($qb$S01C01Q07$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$L$qb$, $qb$When your organisation makes a significant decision that later proves wrong, leadership typically:$qb$, $qb$Conducts a structured post-mortem — what information was missing, what assumption was wrong, what process to change$qb$, $qb$Acknowledges the error informally but moves on without systematic learning$qb$, $qb$Attributes it to external factors — market, competition, timing — rather than the decision process$qb$, $qb$Avoids discussing it — bad decisions are quietly buried$qb$, 5, 3, 2, 1, true),
  ($qb$S01C01Q08$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation generally understand why major leadership decisions are made:$qb$, $qb$Yes — leadership communicates the rationale behind major decisions consistently and clearly$qb$, $qb$Sometimes — rationale is shared for some decisions but not others$qb$, $qb$Rarely — employees are told what to do but not why$qb$, $qb$Never — decisions arrive as directives with no explanation$qb$, 5, 3, 2, 1, true),
  ($qb$S01C01Q09$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$Your organisation's leadership is comfortable making decisions with incomplete information when speed is critical:$qb$, $qb$Yes — leaders make calibrated calls with available data and adjust quickly as more information emerges$qb$, $qb$Sometimes — comfort with ambiguity varies significantly across leaders$qb$, $qb$Rarely — leadership tends to wait for more data even when delay has a cost$qb$, $qb$No — decision paralysis under uncertainty is a known leadership weakness$qb$, 5, 3, 2, 1, true),
  ($qb$S01C01Q10$qb$, $qb$S01$qb$, $qb$C01$qb$, $qb$L+MM+E$qb$, $qb$In your organisation, who effectively has decision-making authority for major operational changes?$qb$, $qb$The person closest to the problem with the right expertise — authority is delegated appropriately$qb$, $qb$Department heads for their areas — but anything cross-functional requires the MD/CEO$qb$, $qb$The MD/CEO for almost everything significant — authority is heavily centralised$qb$, $qb$Unclear — people are uncertain who can actually authorise what$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q01$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$When a committed deadline is missed by a senior leader or department head, what typically follows?$qb$, $qb$A structured review — root cause identified, owner held accountable, corrective action defined and tracked$qb$, $qb$An informal conversation — the miss is acknowledged but rarely has formal consequences$qb$, $qb$The deadline is quietly extended — missing deadlines is normalised at leadership level$qb$, $qb$Nothing — leadership accountability for deadlines is not a real organisational norm$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q02$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$L+MM+E$qb$, $qb$In your organisation, accountability for results is:$qb$, $qb$Clear and consistent — every major outcome has a named owner who is genuinely responsible$qb$, $qb$Partially clear — accountability exists for some functions but is diffuse in others$qb$, $qb$Shared in name but unclear in practice — when things go wrong, ownership is disputed$qb$, $qb$Absent — poor results have no clear owner and no consistent consequence$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q03$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$MM+E$qb$, $qb$When a project fails in your organisation, the most common organisational response is:$qb$, $qb$Structured learning — a post-mortem identifies systemic causes and changes are made to prevent recurrence$qb$, $qb$Individual blame — a person is identified as responsible but the system is not examined$qb$, $qb$External attribution — market conditions, vendors, or regulatory factors are cited$qb$, $qb$Silence — failures are not discussed openly and lessons are not extracted$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q04$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$Leadership commitments made in town halls or all-hands meetings in your organisation are:$qb$, $qb$Tracked and followed up — employees can see progress against what was promised$qb$, $qb$Genuine at the time but not systematically tracked or revisited$qb$, $qb$Treated as aspirational — employees understand they are directional, not binding$qb$, $qb$Not taken seriously — a gap between leadership promises and reality is a known cultural issue$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q05$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$Strategic priorities set at the beginning of the year in your organisation:$qb$, $qb$Are reviewed monthly — progress tracked, owners named, stalled items actively rescued$qb$, $qb$Are reviewed quarterly — useful but too infrequent to catch drift early$qb$, $qb$Are referenced at year-end during appraisals — but not actively tracked during the year$qb$, $qb$Are largely forgotten — new priorities emerge and the annual plan becomes irrelevant$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q06$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$MM+E$qb$, $qb$When a senior leader makes a visible mistake in your organisation, what typically happens?$qb$, $qb$The leader acknowledges it openly — this is seen as a sign of strength and models the accountability culture$qb$, $qb$It is acknowledged privately but not openly — saving face is important at leadership level$qb$, $qb$It is explained away — leadership mistakes are rarely framed as mistakes publicly$qb$, $qb$It is never acknowledged — admitting error at leadership level does not happen in this culture$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q07$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$Performance consequences for persistent underperformance at leadership or senior management level in your organisation are:$qb$, $qb$Real and applied — sustained underperformance at senior level results in structured interventions or exits$qb$, $qb$Inconsistent — some leaders are held accountable, others are protected by tenure or relationships$qb$, $qb$Rare — leadership underperformance is managed through role changes, not accountability conversations$qb$, $qb$Non-existent — senior leaders are not meaningfully held accountable for performance$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q08$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$L+MM+E$qb$, $qb$Action items from leadership or management meetings in your organisation are:$qb$, $qb$Documented, assigned, and reviewed at the next meeting — completion is tracked and expected$qb$, $qb$Documented but follow-up is inconsistent — some are completed, others quietly dropped$qb$, $qb$Verbally agreed but rarely formally tracked$qb$, $qb$Not systematically captured — action items from meetings frequently disappear$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q09$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$E$qb$, $qb$When employees in your organisation raise a concern or suggestion to their manager or leadership, the typical outcome is:$qb$, $qb$A genuine response — concerns are acknowledged, investigated, and employees are updated on the outcome$qb$, $qb$Acknowledged but not always actioned — employees are heard but not always see results$qb$, $qb$Politely noted but rarely leads to any visible change$qb$, $qb$Discouraged — raising concerns is seen as complaining and has no positive outcome$qb$, 5, 3, 2, 1, true),
  ($qb$S01C02Q10$qb$, $qb$S01$qb$, $qb$C02$qb$, $qb$L$qb$, $qb$In your organisation, the leadership team's collective accountability for company-wide results (not just their own function) is:$qb$, $qb$Strong — leaders feel and act on responsibility for overall company outcomes, not just their department$qb$, $qb$Moderate — leaders support the overall agenda but primarily focus on their own function$qb$, $qb$Weak — leaders protect their function first; company-wide accountability is the CEO's problem$qb$, $qb$Non-existent — functional silos mean leaders have no real stake in each other's outcomes$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q01$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$L+MM+E$qb$, $qb$In your organisation, employees who raise uncomfortable truths or point out leadership blind spots are:$qb$, $qb$Valued and protected — speaking up is actively encouraged and visibly rewarded$qb$, $qb$Tolerated — no formal consequences but it does not accelerate careers$qb$, $qb$Managed carefully — there are unwritten rules about what can and cannot be said$qb$, $qb$At risk — employees who challenge leadership face subtle or explicit negative consequences$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q02$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$MM+E$qb$, $qb$When leadership announces a decision that employees believe is wrong, the most common employee response is:$qb$, $qb$Open, respectful challenge through legitimate channels — and leadership genuinely engages with the pushback$qb$, $qb$Private discussion among peers — concerns are aired but not raised formally$qb$, $qb$Quiet compliance — disagreement is swallowed$qb$, $qb$Passive resistance — compliance on paper, sabotage in execution$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q03$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$Leadership in your organisation actively seeks dissenting views before finalising major decisions:$qb$, $qb$Always — devil's advocate positions are deliberately invited; groupthink is actively guarded against$qb$, $qb$Sometimes — when the stakes are high, dissent is sought; in routine decisions it is not$qb$, $qb$Rarely — the leadership team tends toward consensus and dissent is uncomfortable$qb$, $qb$Never — leadership meetings are alignment sessions, not genuine debate forums$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q04$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$MM$qb$, $qb$Middle managers in your organisation feel safe escalating bad news to leadership:$qb$, $qb$Yes — bad news is welcomed early; the messenger is never shot$qb$, $qb$Mostly — escalating bad news is accepted but not always comfortable$qb$, $qb$Rarely — managers filter and soften bad news before it reaches leadership$qb$, $qb$No — the culture of managing upward means leadership rarely hears the real situation$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q05$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$L+MM+E$qb$, $qb$In your organisation, the quality of information that reaches the top leadership is:$qb$, $qb$Accurate and unfiltered — leadership gets the real picture, including bad news$qb$, $qb$Generally accurate but sanitised — uncomfortable details are softened before reaching the top$qb$, $qb$Significantly filtered — leadership sees a curated version of reality$qb$, $qb$Heavily distorted — leadership operates on information that bears little resemblance to ground reality$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q06$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$E$qb$, $qb$When an employee disagrees with their direct manager's approach, they feel:$qb$, $qb$Comfortable raising it directly — disagreement is handled professionally and relationships remain intact$qb$, $qb$Cautious but willing — it depends heavily on the manager's personality$qb$, $qb$Reluctant — raising disagreement creates awkwardness and is usually avoided$qb$, $qb$Unsafe — disagreeing with a manager has visible negative consequences in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q07$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$L+MM$qb$, $qb$Whistleblowing or internal reporting of ethical violations in your organisation is:$qb$, $qb$Supported by a formal mechanism — anonymous reporting exists and is taken seriously$qb$, $qb$Possible but informal — people raise issues directly with trusted seniors$qb$, $qb$Discouraged in practice — reporters face social or professional consequences$qb$, $qb$Non-existent — there is no safe channel for reporting violations and none are expected$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q08$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$L+MM+E$qb$, $qb$In your organisation, meetings where leadership is present are characterised by:$qb$, $qb$Genuine debate — people challenge ideas regardless of hierarchy; the best argument wins$qb$, $qb$Structured discussion — some challenge exists but deference to seniority is visible$qb$, $qb$Presentations to leadership — meetings are reporting sessions, not debate forums$qb$, $qb$Performance — people say what they think leadership wants to hear$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q09$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$MM+E$qb$, $qb$If a frontline employee identified a significant operational risk in your organisation, the path to getting leadership attention would be:$qb$, $qb$Clear and accessible — escalation paths exist and employees know how to use them$qb$, $qb$Possible but uncertain — it depends on having the right manager who will pass it up$qb$, $qb$Difficult — the hierarchy filters most upward communication$qb$, $qb$Effectively blocked — frontline insights rarely reach leadership level$qb$, 5, 3, 2, 1, true),
  ($qb$S01C03Q10$qb$, $qb$S01$qb$, $qb$C03$qb$, $qb$L$qb$, $qb$Leadership in your organisation responds to internal criticism or negative employee feedback by:$qb$, $qb$Engaging with it seriously — critical feedback is investigated, responded to, and used to drive change$qb$, $qb$Acknowledging it selectively — some feedback is acted on; uncomfortable feedback is noted but not actioned$qb$, $qb$Managing it — feedback is addressed in communications but rarely leads to real change$qb$, $qb$Dismissing it — internal criticism is attributed to negativity or misunderstanding$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q01$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$During a significant business crisis (revenue collapse, regulatory action, major talent exodus), leadership in your organisation:$qb$, $qb$Becomes more visible and communicative — takes clear ownership, communicates frequently, makes fast decisions$qb$, $qb$Manages the crisis but communication to the broader organisation is delayed or partial$qb$, $qb$Goes quiet — employees learn about serious crises through rumour before official communication$qb$, $qb$Fragments — leadership loses cohesion; mixed messages and visible panic reach employees$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q02$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$L+MM+E$qb$, $qb$When your organisation goes through major change (restructuring, new strategy, leadership change), employees experience:$qb$, $qb$Clear communication — what is changing, why, what it means for them, and what comes next$qb$, $qb$General awareness — the change is announced but details and implications are unclear$qb$, $qb$Anxiety and rumour — official communication lags behind informal speculation$qb$, $qb$Shock — changes are announced with little preparation and minimal explanation$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q03$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$Your organisation's leadership has a documented crisis response playbook or protocol:$qb$, $qb$Yes — scenarios are pre-mapped, response teams named, communication templates ready$qb$, $qb$Partially — some scenarios have been thought through but no formal playbook exists$qb$, $qb$No — crisis response is improvised each time$qb$, $qb$No — and past crises have revealed this gap without it being addressed$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q04$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$MM+E$qb$, $qb$In your organisation, major change initiatives are championed by leaders who:$qb$, $qb$Stay visibly involved throughout — attend key sessions, remove blockers, personally reinforce the change$qb$, $qb$Launch the initiative with energy but hand it off to a team after the kickoff$qb$, $qb$Endorse the change in communications but are not visibly involved in execution$qb$, $qb$Are largely absent — change initiatives run without visible leadership sponsorship$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q05$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$When external disruption hits your industry (new technology, regulatory shift, economic shock), leadership in your organisation:$qb$, $qb$Responds proactively — scenario planning is done before disruption hits; response plans are ready$qb$, $qb$Responds adequately — adapts when required but is rarely ahead of disruption$qb$, $qb$Reacts slowly — disruption is often underestimated until it creates a visible problem$qb$, $qb$Is caught off guard — external disruptions consistently surprise leadership$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q06$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$L+MM+E$qb$, $qb$Employee morale during periods of organisational difficulty or uncertainty in your organisation is:$qb$, $qb$Maintained through proactive leadership communication and visible stability at the top$qb$, $qb$Mixed — some leaders stabilise their teams well; others create more anxiety than they resolve$qb$, $qb$Noticeably impacted — uncertainty at the top cascades quickly into employee anxiety$qb$, $qb$Severely damaged — leadership's handling of difficult periods is a known morale killer$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q07$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$L$qb$, $qb$Your organisation's track record of successfully completing major transformation initiatives is:$qb$, $qb$Strong — most major initiatives reach completion with measurable outcomes$qb$, $qb$Mixed — some initiatives succeed; others lose momentum after the initial phase$qb$, $qb$Weak — initiatives are launched regularly but rarely completed as originally designed$qb$, $qb$Poor — transformation fatigue is visible; employees are sceptical of new initiatives$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q08$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$MM+E$qb$, $qb$Leadership communication during periods of organisational uncertainty in your organisation is:$qb$, $qb$Frequent, honest, and two-way — leadership communicates what they know and invites questions$qb$, $qb$Periodic and generally positive — communication increases but bad news is softened$qb$, $qb$Infrequent — employees are left to interpret silence$qb$, $qb$Absent or misleading — what leadership communicates during hard times does not match reality$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q09$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$When your organisation faces competitive pressure that threatens market position, leadership's response is:$qb$, $qb$Swift and structured — a named team is activated, options are mapped, a response strategy is implemented within weeks$qb$, $qb$Deliberate — competitive threats are discussed and a response is formulated but takes months$qb$, $qb$Slow — competitive threats are often acknowledged late and responses are reactive$qb$, $qb$Absent — competitive pressure is not met with a structured organisational response$qb$, 5, 3, 2, 1, true),
  ($qb$S01C04Q10$qb$, $qb$S01$qb$, $qb$C04$qb$, $qb$L+MM+E$qb$, $qb$When your organisation went through its last significant restructuring or change, employees felt:$qb$, $qb$Informed and supported — the rationale was clear and transition support was provided$qb$, $qb$Informed but anxious — the what was communicated but the why and what-next were unclear$qb$, $qb$Blindsided — the change came with little preparation or communication$qb$, $qb$Betrayed — promises made before or during the change were not kept$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q01$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$L+MM+E$qb$, $qb$When leadership in your organisation faces a decision that is profitable but ethically questionable, they typically:$qb$, $qb$Decline — ethics are treated as a non-negotiable constraint even when the financial cost is significant$qb$, $qb$Deliberate carefully — ethics are considered seriously but the outcome depends on the specific situation$qb$, $qb$Find a justification — the profitable option is usually taken with a rationale constructed around it$qb$, $qb$Choose profit — ethical considerations are secondary to financial outcomes in practice$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q02$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$L+MM$qb$, $qb$The values stated on your organisation's website or in your culture documents match what actually happens day-to-day:$qb$, $qb$Closely — stated values are visibly reflected in how decisions are made and how people are treated$qb$, $qb$Partially — some values are lived; others are aspirational$qb$, $qb$Weakly — there is a visible gap between stated values and actual organisational behaviour$qb$, $qb$Not at all — stated values are marketing material; actual culture is significantly different$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q03$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$L$qb$, $qb$Leadership in your organisation models the behaviours they expect from employees:$qb$, $qb$Consistently — leaders visibly live the standards they set; there is no 'rules for thee, not for me'$qb$, $qb$Mostly — leadership generally models expected behaviour but there are visible exceptions$qb$, $qb$Inconsistently — employees notice the gap between what leaders say and what they do$qb$, $qb$Rarely — leadership operates by different standards from those applied to the rest of the organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q04$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$MM+E$qb$, $qb$Favouritism, nepotism, or political dynamics visibly influence decisions in your organisation (promotions, projects, resources):$qb$, $qb$Rarely — decisions are predominantly merit-based and the process is seen as fair$qb$, $qb$Sometimes — there are perceived favourites but it is not the dominant dynamic$qb$, $qb$Frequently — political relationships are a significant factor in who gets what$qb$, $qb$Always — who you know is more important than what you deliver in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q05$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$L+MM$qb$, $qb$When regulatory, legal, or statutory requirements conflict with business convenience in your organisation, leadership:$qb$, $qb$Always complies — no business case justifies regulatory risk; this is a firm line$qb$, $qb$Generally complies — occasional grey areas are navigated carefully$qb$, $qb$Sometimes cuts corners — regulatory requirements are treated as negotiable when the business case is strong$qb$, $qb$Regularly takes risk — non-compliance is a known and accepted part of doing business here$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q06$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$L+MM+E$qb$, $qb$Leadership in your organisation treats all employees with consistent dignity regardless of their level, function, or background:$qb$, $qb$Yes — respectful treatment is a visible and enforced standard across all levels$qb$, $qb$Mostly — the culture is generally respectful but inconsistencies exist$qb$, $qb$Inconsistently — treatment varies significantly based on seniority or relationships$qb$, $qb$No — disrespectful treatment of lower-level employees by leadership is a visible and unaddressed issue$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q07$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$L$qb$, $qb$Your organisation has a code of conduct or ethics policy that is:$qb$, $qb$Active — employees know it, training is provided, violations are investigated and acted on$qb$, $qb$Documented — exists and is communicated during onboarding but not actively reinforced$qb$, $qb$Exists on paper — available if someone looks for it but not part of organisational life$qb$, $qb$Non-existent or outdated — no functional ethics framework exists$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q08$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$MM+E$qb$, $qb$When a leader in your organisation is found to have behaved unethically, the organisational response is:$qb$, $qb$Consistent and visible — the behaviour is investigated and consequences applied regardless of seniority$qb$, $qb$Case-dependent — serious violations are addressed; minor ones are managed quietly$qb$, $qb$Protective — leaders are shielded from consequences that would apply to lower-level employees$qb$, $qb$Non-existent — ethical violations by leaders are not addressed and the culture knows it$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q09$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$L+MM+E$qb$, $qb$The organisation's commitment to employee welfare (health, safety, fair pay, dignity) relative to commercial pressures is:$qb$, $qb$Genuine — employee welfare is treated as a business priority, not a compliance obligation$qb$, $qb$Adequate — minimum standards are met but welfare is not a strategic priority$qb$, $qb$Inconsistent — welfare commitments are made publicly but cut when under commercial pressure$qb$, $qb$Performative — welfare messaging exists but practice is significantly below what is communicated$qb$, 5, 3, 2, 1, true),
  ($qb$S01C05Q10$qb$, $qb$S01$qb$, $qb$C05$qb$, $qb$L$qb$, $qb$Leadership in your organisation is transparent about the organisation's financial health and business challenges with employees:$qb$, $qb$Yes — employees receive regular, honest updates on business performance including challenges$qb$, $qb$Partially — good news is shared widely; bad news is shared selectively or softened$qb$, $qb$Rarely — financial and business information is treated as leadership-only knowledge$qb$, $qb$No — employees are deliberately kept uninformed about business realities$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q01$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$L$qb$, $qb$If your MD/CEO left tomorrow, your organisation's leadership continuity would be:$qb$, $qb$Secure — a named successor is identified, developed, and ready to step up$qb$, $qb$Manageable — there are capable people who could fill the role, though transition would take time$qb$, $qb$Difficult — there is no clear successor and significant capability would need to be hired$qb$, $qb$Catastrophic — the organisation is wholly dependent on one person at the top$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q02$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$L+MM$qb$, $qb$Leadership development in your organisation is:$qb$, $qb$Systematic — high-potential employees are identified, developed, and given stretch assignments on a planned basis$qb$, $qb$Opportunistic — good people get development when it is available but there is no systematic pipeline$qb$, $qb$Reactive — leadership development happens in response to gaps, not to build for the future$qb$, $qb$Non-existent — the organisation hires leaders externally when needed rather than building them internally$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q03$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$L$qb$, $qb$Senior leaders in your organisation actively invest time in developing the people below them:$qb$, $qb$Yes — mentoring, coaching, and stretch assignments are a visible leadership priority$qb$, $qb$Partially — some leaders are strong developers; others focus entirely on delivery$qb$, $qb$Rarely — leaders are too focused on their own deliverables to invest in developing others$qb$, $qb$No — people development is HR's job in this organisation; line leaders do not see it as their responsibility$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q04$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$MM$qb$, $qb$Middle managers in your organisation who demonstrate leadership potential are:$qb$, $qb$Identified and actively developed — there is a visible and fair process for spotting and growing talent$qb$, $qb$Recognised informally — good people get noticed but the process is relationship-dependent$qb$, $qb$Left to prove themselves — potential is recognised only after sustained delivery over years$qb$, $qb$Not systematically identified — talent at middle management level is not mapped or developed$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q05$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$L+MM$qb$, $qb$Your organisation's current leadership team has the capability to lead the business at 2x its current scale:$qb$, $qb$Yes — the team has the mindset, skills, and bandwidth to lead at significantly greater scale$qb$, $qb$Partially — some leaders are scale-ready; others would struggle at a larger organisation$qb$, $qb$Unlikely — the current team was built for the current size; scale would require significant external hires$qb$, $qb$No — leadership capability is already stretched at current scale$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q06$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$L$qb$, $qb$Succession plans for the top 10 leadership roles in your organisation are:$qb$, $qb$Documented, reviewed annually, and actively managed — successors are known and being developed$qb$, $qb$Informally identified — there are people in mind but no formal plan or development track$qb$, $qb$Partially done — succession is planned for a few critical roles but not systematically$qb$, $qb$Non-existent — succession planning has not been done for any leadership role$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q07$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$MM+E$qb$, $qb$Career paths for high-performing employees in your organisation are:$qb$, $qb$Clear and communicated — employees know what growth looks like and what is required to achieve it$qb$, $qb$Visible for some roles — paths are clearer in some functions than others$qb$, $qb$Vague — employees generally do not know what career progression looks like$qb$, $qb$Non-existent — career growth is entirely at management discretion with no visible framework$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q08$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$L+MM$qb$, $qb$External leadership hires in your organisation over the last 3 years have:$qb$, $qb$Succeeded — external hires have integrated well, delivered impact, and stayed$qb$, $qb$Mixed — some have succeeded; others have not integrated well or have left within 18 months$qb$, $qb$Struggled — external hires frequently fail to integrate into the culture or deliver expected impact$qb$, $qb$Failed consistently — external leadership hiring is a known and expensive problem$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q09$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$L$qb$, $qb$Leadership diversity (gender, background, experience, thinking style) in your organisation's top team is:$qb$, $qb$Actively pursued — diversity of perspective at the top is seen as a strategic advantage and is managed for$qb$, $qb$Acknowledged — diversity is valued in principle but the top team remains relatively homogeneous$qb$, $qb$Not prioritised — leadership selection is based on technical competence and relationship networks$qb$, $qb$Not considered — leadership diversity is not on the agenda$qb$, 5, 3, 2, 1, true),
  ($qb$S01C06Q10$qb$, $qb$S01$qb$, $qb$C06$qb$, $qb$MM+E$qb$, $qb$When a senior leader exits your organisation, the knowledge, relationships, and institutional memory they hold:$qb$, $qb$Are systematically transferred — handover processes ensure continuity$qb$, $qb$Are partially transferred — key relationships are handed over but institutional knowledge is often lost$qb$, $qb$Are largely lost — exits create visible capability and knowledge gaps$qb$, $qb$Are entirely lost — the organisation has no process for capturing or transferring leadership knowledge$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q01$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$L+MM+E$qb$, $qb$Leadership communication in your organisation reaches all employees:$qb$, $qb$Reliably — multiple channels are used; leadership verifies messages have been received and understood$qb$, $qb$Mostly — communication reaches most employees but frontline and field staff sometimes miss key messages$qb$, $qb$Inconsistently — messages cascade differently across departments and levels$qb$, $qb$Poorly — a significant portion of the workforce is regularly out of the loop on important matters$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q02$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$L$qb$, $qb$Leadership in your organisation communicates the organisation's strategy in a way that employees can connect to their daily work:$qb$, $qb$Effectively — employees at all levels understand how their role contributes to the organisation's direction$qb$, $qb$Partially — senior employees understand the strategy; frontline employees have limited visibility$qb$, $qb$Weakly — the strategy exists but is not communicated in a way that is meaningful to most employees$qb$, $qb$Not at all — most employees have no meaningful understanding of where the organisation is headed$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q03$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$MM+E$qb$, $qb$The frequency of structured communication from leadership to employees in your organisation is:$qb$, $qb$Regular and rhythmic — monthly or quarterly all-hands, weekly manager briefings, clear communication calendar$qb$, $qb$Periodic — formal communication happens several times a year but lacks a consistent rhythm$qb$, $qb$Reactive — leadership communicates mainly when there is a crisis or major announcement$qb$, $qb$Rare — employees go weeks or months without structured communication from leadership$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q04$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$L+MM$qb$, $qb$Leadership in your organisation acknowledges and addresses rumours or misinformation that circulate internally:$qb$, $qb$Proactively — leadership monitors the pulse and addresses misinformation before it spreads$qb$, $qb$Reactively — misinformation is addressed after it has already spread$qb$, $qb$Rarely — leadership tends to ignore rumours rather than address them$qb$, $qb$Never — the rumour mill runs unchecked and is a recognised morale and trust problem$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q05$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$L+MM+E$qb$, $qb$When your organisation achieves a significant milestone or success, leadership:$qb$, $qb$Celebrates it visibly — the achievement is communicated widely, teams are recognised, and the win is connected to the larger mission$qb$, $qb$Acknowledges it — a note or announcement is made but recognition is limited$qb$, $qb$Moves on quickly — success is expected and not meaningfully celebrated$qb$, $qb$Does not acknowledge it — milestones pass without recognition$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q06$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$E$qb$, $qb$Employees in your organisation know who to contact and through which channel when they have concerns about their work, team, or the organisation:$qb$, $qb$Yes — communication channels, escalation paths, and contact points are clearly communicated$qb$, $qb$Mostly — most employees know their manager is the first point of contact but beyond that it is unclear$qb$, $qb$Partially — some employees know their options; others do not$qb$, $qb$No — employees do not know where to go with concerns and often don't bother trying$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q07$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$L+MM$qb$, $qb$Organisational decisions that affect employees' roles, teams, or ways of working are communicated to affected employees:$qb$, $qb$Before implementation — employees hear from leadership before changes take effect$qb$, $qb$At announcement — employees learn at the same time as the general communication$qb$, $qb$During implementation — employees find out when the change is already underway$qb$, $qb$After the fact — employees sometimes discover changes have already happened$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q08$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$L+MM+E$qb$, $qb$Two-way communication (leadership listening to employees, not just broadcasting) in your organisation is:$qb$, $qb$Structured and genuine — regular pulse surveys, town hall Q&As, skip-level meetings with real follow-through$qb$, $qb$Occasional — some listening mechanisms exist but are infrequent or feel performative$qb$, $qb$Rare — communication is predominantly top-down with limited genuine upward flow$qb$, $qb$Non-existent — leadership does not have structured mechanisms for hearing from employees$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q09$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$MM$qb$, $qb$Middle managers in your organisation receive leadership messages with enough context to brief their teams effectively:$qb$, $qb$Always — managers are briefed before wider communication and given context to answer team questions$qb$, $qb$Usually — managers get advance notice but sometimes learn at the same time as their teams$qb$, $qb$Rarely — managers often find out about decisions at the same time as everyone else$qb$, $qb$Never — managers are as surprised as their teams by leadership announcements$qb$, 5, 3, 2, 1, true),
  ($qb$S01C07Q10$qb$, $qb$S01$qb$, $qb$C07$qb$, $qb$L+MM+E$qb$, $qb$When your organisation faces a public reputation issue (press coverage, social media, regulatory action), internal communication to employees is:$qb$, $qb$Fast and honest — leadership briefs employees before or alongside external communication$qb$, $qb$Delayed — employees often learn from external sources before receiving internal communication$qb$, $qb$Absent — employees are expected to read external coverage for information$qb$, $qb$Counterproductive — internal and external messaging conflict, creating confusion$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q01$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$L+MM$qb$, $qb$Leadership in your organisation actively follows and responds to trends reshaping your industry (AI, automation, regulatory change, consumer shifts):$qb$, $qb$Yes — external trends are tracked, discussed in leadership forums, and shape strategic decisions$qb$, $qb$Partially — leadership is broadly aware but trend monitoring is informal and reactive$qb$, $qb$Weakly — leadership engages with trends when they become impossible to ignore$qb$, $qb$No — external trends are not a structured part of leadership thinking$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q02$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$L+MM+E$qb$, $qb$New ideas from employees at any level in your organisation are:$qb$, $qb$Actively solicited — formal mechanisms exist to capture, evaluate, and implement employee ideas$qb$, $qb$Welcome informally — good ideas get traction if raised with the right manager$qb$, $qb$Rarely actioned — employees have learned that suggesting ideas leads nowhere$qb$, $qb$Discouraged — the culture rewards execution of existing plans, not challenge or innovation$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q03$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$L$qb$, $qb$Leadership in your organisation visits, benchmarks, or learns from organisations in other industries or geographies:$qb$, $qb$Regularly — cross-industry and cross-geography learning is a structured leadership practice$qb$, $qb$Occasionally — some leaders seek external exposure but it is not systematic$qb$, $qb$Rarely — learning is primarily from within the industry$qb$, $qb$Never — external benchmarking is not part of leadership practice$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q04$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$L+MM$qb$, $qb$When a team or individual in your organisation experiments with a new approach and it fails, leadership responds by:$qb$, $qb$Treating it as learning — failure from genuine experimentation is discussed openly and used to inform future attempts$qb$, $qb$Tolerating it — no formal consequences but the failure is not discussed openly either$qb$, $qb$Discouraging — teams that try new things and fail are less likely to try again$qb$, $qb$Punishing — visible failure has career consequences, which kills experimentation$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q05$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$L+MM+E$qb$, $qb$The adoption of new technology (including AI tools) by leadership and management in your organisation is:$qb$, $qb$Proactive — leadership champions technology adoption and models it personally$qb$, $qb$Selective — some leaders adopt new tools enthusiastically; others resist$qb$, $qb$Slow — technology adoption at leadership level lags behind what is available$qb$, $qb$Resistant — leadership is a barrier to technology adoption rather than a champion$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q06$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$L$qb$, $qb$Strategic planning in your organisation incorporates scenarios for futures significantly different from the present:$qb$, $qb$Yes — scenario planning for disruption, discontinuity, and alternative futures is a standard practice$qb$, $qb$Partially — some scenario thinking happens but planning is primarily extrapolation of current trends$qb$, $qb$Rarely — planning assumes a broadly similar future to today$qb$, $qb$No — strategic planning is an annual budget exercise, not a genuine futures exploration$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q07$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$MM+E$qb$, $qb$The organisation's investment in learning and development relative to industry benchmarks is:$qb$, $qb$Above average — training budgets are protected even under cost pressure; learning is treated as investment$qb$, $qb$Average — adequate investment but not a strategic differentiator$qb$, $qb$Below average — training is the first budget cut under cost pressure$qb$, $qb$Minimal — formal learning investment is effectively zero$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q08$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$L+MM$qb$, $qb$Your organisation's approach to AI and automation is:$qb$, $qb$Strategic — a clear AI adoption roadmap exists, pilots are running, and leadership understands the implications$qb$, $qb$Exploratory — some teams are experimenting with AI but there is no organisation-wide strategy$qb$, $qb$Cautious — AI is acknowledged as important but no real adoption is happening$qb$, $qb$Absent — AI is not on the leadership agenda in any meaningful way$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q09$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$L+MM+E$qb$, $qb$Learning from competitors — what they do well, what they do differently — in your organisation is:$qb$, $qb$Structured — competitor analysis is a regular practice that feeds into strategic decisions$qb$, $qb$Informal — competitive awareness exists but is not systematically captured or shared$qb$, $qb$Reactive — competitors are studied only when they take an action that directly impacts the business$qb$, $qb$Absent — the organisation does not systematically study or learn from competitors$qb$, 5, 3, 2, 1, true),
  ($qb$S01C08Q10$qb$, $qb$S01$qb$, $qb$C08$qb$, $qb$L$qb$, $qb$Leadership in your organisation engages with external advisors, consultants, or board members to challenge their thinking:$qb$, $qb$Regularly and genuinely — external perspectives are actively sought and meaningfully influence decisions$qb$, $qb$Occasionally — external advice is sought for specific projects but not as a strategic habit$qb$, $qb$Rarely — external advisors are used for compliance or optics, not genuine strategic challenge$qb$, $qb$Never — leadership relies entirely on internal perspective$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q01$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$L+MM+E$qb$, $qb$The level of decision-making authority given to department heads and managers in your organisation is:$qb$, $qb$Appropriate — people have real authority commensurate with their accountability$qb$, $qb$Partial — authority exists in theory but significant decisions require senior sign-off$qb$, $qb$Limited — most meaningful decisions require escalation regardless of the manager's seniority$qb$, $qb$Minimal — authority is centralised at the top; managers execute but do not decide$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q02$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$L+MM$qb$, $qb$Micromanagement — leaders closely controlling how work is done rather than what outcomes to achieve — in your organisation is:$qb$, $qb$Rare — leaders set clear outcomes and give teams genuine freedom in how they achieve them$qb$, $qb$Moderate — some leaders empower their teams; others are hands-on to the point of interference$qb$, $qb$Common — managers at most levels check in too frequently and override team decisions$qb$, $qb$Pervasive — micromanagement is a defining characteristic of the management culture$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q03$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$MM+E$qb$, $qb$When employees in your organisation are given a new responsibility or project, they receive:$qb$, $qb$Clear brief, real authority, adequate resources, and genuine support — set up to succeed$qb$, $qb$The task is clear but authority and resources are partial — they have to fight for what they need$qb$, $qb$The task but not the authority or resources — responsibility without power$qb$, $qb$The task with minimal context — figure it out yourself is the dominant approach$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q04$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$L$qb$, $qb$The MD/CEO in your organisation is involved in decisions that should be made at department head or manager level:$qb$, $qb$Rarely — the CEO operates at the strategic level; operational decisions are genuinely delegated$qb$, $qb$Sometimes — the CEO is occasionally drawn into operational decisions they shouldn't need to touch$qb$, $qb$Frequently — significant operational decisions routinely reach the CEO$qb$, $qb$Almost always — the CEO is the de facto decision-maker for most significant matters$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q05$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$L+MM$qb$, $qb$Approval processes for routine business decisions (vendor selection, budget spend within defined limits, hiring) in your organisation are:$qb$, $qb$Fast and delegated — defined authority levels mean most routine decisions are made without senior sign-off$qb$, $qb$Adequate — approvals happen within reasonable timeframes but involve more levels than necessary$qb$, $qb$Slow — routine decisions take longer than they should due to approval bottlenecks$qb$, $qb$A significant operational drag — approval processes are widely acknowledged as a business problem$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q06$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation who take initiative and make reasonable decisions without waiting for approval are:$qb$, $qb$Celebrated — taking initiative within one's scope is actively encouraged and rewarded$qb$, $qb$Tolerated — initiative is acceptable if the outcome is good but the risk is borne by the individual$qb$, $qb$Cautious — most employees wait for direction rather than risk acting without approval$qb$, $qb$Penalised — acting without explicit approval is seen as overstepping regardless of outcome$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q07$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$L+MM$qb$, $qb$When a manager in your organisation delegates a task and the employee completes it differently from how the manager would have done it (but achieves the outcome), the typical response is:$qb$, $qb$Positive — outcome achievement is what matters; different approaches are respected and sometimes adopted$qb$, $qb$Neutral — the outcome is accepted but the different approach is noted for next time$qb$, $qb$Uncomfortable — managers prefer their approach to be followed even when alternatives work$qb$, $qb$Negative — employees who deviate from the prescribed approach face criticism regardless of outcome$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q08$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$L+MM+E$qb$, $qb$The delegation of authority in your organisation is:$qb$, $qb$Formally defined — a documented authority matrix specifies who can decide what at each level$qb$, $qb$Informally understood — delegation norms exist but are not formally documented$qb$, $qb$Ambiguous — employees are frequently unsure what they can decide independently$qb$, $qb$Non-existent — authority is entirely relationship-based and changes based on mood and context$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q09$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$E$qb$, $qb$Employees in your organisation feel they have enough authority to do their jobs effectively without constant escalation:$qb$, $qb$Yes — employees are empowered to make the decisions their role requires$qb$, $qb$Mostly — sufficient authority for routine matters but limited for anything outside the norm$qb$, $qb$Partially — employees regularly need approvals for things they should be able to decide$qb$, $qb$No — employees feel constrained and unable to act effectively within their role$qb$, 5, 3, 2, 1, true),
  ($qb$S01C09Q10$qb$, $qb$S01$qb$, $qb$C09$qb$, $qb$L+MM$qb$, $qb$Leadership in your organisation trusts managers to represent the organisation's values and make sound judgements without supervision:$qb$, $qb$Yes — leadership demonstrates trust through genuinely hands-off management of competent managers$qb$, $qb$Partially — trust is extended to some managers but withheld from others based on past performance or relationships$qb$, $qb$Conditionally — trust exists until something goes wrong, after which it is withdrawn and oversight increases$qb$, $qb$No — the culture assumes managers need to be watched; autonomy is not genuinely extended$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q01$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$L+MM+E$qb$, $qb$Employees in your organisation believe that what leadership says in meetings, communications, and town halls actually reflects what leadership thinks and intends:$qb$, $qb$Yes — leadership is seen as authentic; there is no significant gap between public and private positions$qb$, $qb$Mostly — leadership is generally trusted but employees know some messages are managed$qb$, $qb$Partially — employees have learned to read between the lines of official communication$qb$, $qb$No — a significant credibility gap exists between what leadership says and what employees believe$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q02$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$MM+E$qb$, $qb$The level of trust employees have in the organisation's senior leadership team is:$qb$, $qb$High — employees believe leadership has the organisation's best interests at heart and is competent to lead it$qb$, $qb$Moderate — trust exists but is conditional and has been tested by past decisions$qb$, $qb$Low — a significant portion of employees are sceptical of leadership's intentions or competence$qb$, $qb$Very low — distrust of leadership is a visible and damaging organisational dynamic$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q03$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$L+MM$qb$, $qb$When leadership makes a commitment to employees (policy change, investment, promotion process, culture initiative) and circumstances change, they:$qb$, $qb$Communicate honestly — explain what changed, why, and what it means for the original commitment$qb$, $qb$Quietly adjust — the commitment is modified without explicit acknowledgement$qb$, $qb$Ignore it — changed commitments are not addressed and employees are expected to move on$qb$, $qb$Deny it — leadership does not acknowledge that a commitment was made$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q04$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$L+MM+E$qb$, $qb$Leadership consistency — behaving the same way whether being observed or not, in good times and bad — in your organisation is:$qb$, $qb$Strong — leaders are known for behaving consistently regardless of context or audience$qb$, $qb$Moderate — most leaders are consistent but there are visible exceptions$qb$, $qb$Weak — significant differences in behaviour depending on who is watching$qb$, $qb$Poor — leadership inconsistency is a known and discussed organisational problem$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q05$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$E$qb$, $qb$If asked whether they would recommend your organisation to a talented friend as a great place to work, most employees in your organisation would:$qb$, $qb$Enthusiastically recommend it — employees are genuine advocates for the organisation$qb$, $qb$Recommend it with caveats — it is good in some ways but they would flag specific concerns$qb$, $qb$Be hesitant — employees would not actively recommend the organisation$qb$, $qb$Discourage it — employees would warn friends away from joining$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q06$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$L+MM$qb$, $qb$Leadership in your organisation admits uncertainty or says 'I don't know' when they genuinely don't:$qb$, $qb$Comfortably — acknowledging the limits of one's knowledge is seen as honest and respected$qb$, $qb$Sometimes — a few leaders model this; others feel compelled to have an answer regardless$qb$, $qb$Rarely — admitting uncertainty is seen as a leadership weakness in this culture$qb$, $qb$Never — leaders are expected to have answers and admitting uncertainty is not acceptable$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q07$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$L+MM+E$qb$, $qb$The gap between what leadership says about the organisation's culture and what employees experience day-to-day is:$qb$, $qb$Minimal — what is said matches what is lived$qb$, $qb$Noticeable — some aspects of culture match the narrative; others do not$qb$, $qb$Significant — employees privately acknowledge a gap but this is not discussed openly$qb$, $qb$Very large — the stated culture and the experienced culture are fundamentally different$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q08$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$MM+E$qb$, $qb$When leadership makes an unpopular decision, they:$qb$, $qb$Explain the rationale honestly — even when the decision cannot be reversed, the reasoning is shared openly$qb$, $qb$Announce the decision and invite questions — some explanation is offered$qb$, $qb$Announce the decision without meaningful explanation — employees are expected to accept it$qb$, $qb$Avoid or delay announcement — unpopular decisions are communicated poorly or not at all$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q09$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$L$qb$, $qb$The leadership team in your organisation is seen by employees as:$qb$, $qb$United and credible — a cohesive team that employees respect and trust to lead the organisation effectively$qb$, $qb$Competent but political — capable individually but the team dynamic is not always healthy$qb$, $qb$Divided — employees are aware of tensions and factions within the leadership team$qb$, $qb$Dysfunctional — leadership team dynamics are a visible drag on organisational performance$qb$, 5, 3, 2, 1, true),
  ($qb$S01C10Q10$qb$, $qb$S01$qb$, $qb$C10$qb$, $qb$L+MM+E$qb$, $qb$Organisational trust — the belief that the organisation will act fairly and in employees' interests — in your organisation is:$qb$, $qb$High — employees give leadership the benefit of the doubt; trust is the default$qb$, $qb$Moderate — trust has to be earned; cynicism exists but is not dominant$qb$, $qb$Low — employees approach leadership communication and decisions with scepticism$qb$, $qb$Broken — a specific event or pattern of behaviour has damaged trust and it has not been rebuilt$qb$, 5, 3, 2, 1, true);
INSERT INTO question_bank (question_id, section_code, category_code, level_tag, text, option_a, option_b, option_c, option_d, score_a, score_b, score_c, score_d, active) VALUES
  ($qb$S02C01Q01$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$L+MM+E$qb$, $qb$When managers in your organisation deliver bad news (missed targets, rejected proposals, negative feedback), they do so:$qb$, $qb$Directly and honestly — the facts are delivered clearly, without softening to the point of distortion$qb$, $qb$Generally honestly but with significant softening — the message is clear but edges are rounded$qb$, $qb$Vaguely — bad news is often buried in positive framing so the real message is unclear$qb$, $qb$Not at all — bad news is withheld, delayed, or communicated through others to avoid discomfort$qb$, 5, 3, 2, 1, true),
  ($qb$S02C01Q02$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$MM+E$qb$, $qb$When a manager in your organisation makes a commitment to a team member and cannot keep it, the typical response is:$qb$, $qb$Proactive acknowledgement — the manager informs the person before the deadline, explains why, and offers an alternative$qb$, $qb$Reactive acknowledgement — the manager admits the miss after the fact and apologises$qb$, $qb$Silence — broken commitments are rarely acknowledged or explained$qb$, $qb$Denial — managers in this organisation do not acknowledge broken commitments$qb$, 5, 3, 2, 1, true),
  ($qb$S02C01Q03$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$Reporting of performance data (sales numbers, project status, quality metrics) to leadership in your organisation is:$qb$, $qb$Accurate and unembellished — numbers are reported as they are, including unflattering data$qb$, $qb$Generally accurate but selectively presented — positive data is emphasised; negatives are noted but minimised$qb$, $qb$Managed — reports are structured to show the best possible picture$qb$, $qb$Distorted — significant gaps exist between reported performance and actual performance$qb$, 5, 3, 2, 1, true),
  ($qb$S02C01Q04$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$L+MM+E$qb$, $qb$When an error is made by a manager or team in your organisation, the default response is:$qb$, $qb$Transparent acknowledgement — the error is openly admitted, ownership is taken, and corrective action is communicated$qb$, $qb$Private acknowledgement — the error is addressed internally but not communicated beyond the immediate team$qb$, $qb$Deflection — the error is minimised or attributed to external factors$qb$, $qb$Cover-up — errors are concealed for as long as possible$qb$, 5, 3, 2, 1, true),
  ($qb$S02C01Q05$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$MM+E$qb$, $qb$Managers in your organisation tell employees what they want to hear rather than what they need to hear:$qb$, $qb$Rarely — managers are known for honest, sometimes uncomfortable, feedback and communication$qb$, $qb$Sometimes — honesty depends heavily on the manager's personality and the stakes involved$qb$, $qb$Frequently — people-pleasing is a visible management pattern in this organisation$qb$, $qb$Almost always — candid communication from managers is the exception, not the norm$qb$, 5, 3, 2, 1, true),
  ($qb$S02C01Q06$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$L+MM$qb$, $qb$Forecasts and projections presented by management in your organisation to the board, investors, or senior leadership are:$qb$, $qb$Realistic and range-based — best case, base case, and downside scenarios are presented$qb$, $qb$Optimistic but grounded — projections lean positive but are based on real assumptions$qb$, $qb$Consistently optimistic — projections regularly exceed actual outcomes$qb$, $qb$Fabricated or aspirational — projections bear little relationship to operational reality$qb$, 5, 3, 2, 1, true),
  ($qb$S02C01Q07$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$L+MM+E$qb$, $qb$When employees ask direct questions of their managers in your organisation, the answers they receive are:$qb$, $qb$Direct and complete — managers answer what they know and acknowledge what they don't$qb$, $qb$Generally responsive but sometimes evasive on sensitive topics$qb$, $qb$Frequently evasive — answers are technically true but not fully informative$qb$, $qb$Unreliable — employees have learned that manager responses cannot be taken at face value$qb$, 5, 3, 2, 1, true),
  ($qb$S02C01Q08$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$MM$qb$, $qb$Middle managers in your organisation accurately represent employee concerns to senior leadership:$qb$, $qb$Yes — managers are known as reliable conduits for upward communication, even when it is uncomfortable$qb$, $qb$Mostly — significant concerns make it up; minor ones are filtered$qb$, $qb$Selectively — managers communicate concerns they believe leadership wants to hear$qb$, $qb$No — employee concerns are systematically filtered before reaching leadership$qb$, 5, 3, 2, 1, true),
  ($qb$S02C01Q09$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$L+MM+E$qb$, $qb$The gap between what managers say privately and what they say in official settings in your organisation is:$qb$, $qb$Minimal — managers communicate consistently in private and in public$qb$, $qb$Noticeable on some topics — managers are more candid in private on sensitive issues$qb$, $qb$Significant — the private view and the official position are frequently at odds$qb$, $qb$Extreme — a formal double-speak culture exists where public and private positions are entirely different$qb$, 5, 3, 2, 1, true),
  ($qb$S02C01Q10$qb$, $qb$S02$qb$, $qb$C01$qb$, $qb$E$qb$, $qb$Employees in your organisation trust the accuracy of official internal communications (announcements, policy updates, performance communications):$qb$, $qb$Yes — official communications are seen as accurate and reliable$qb$, $qb$Mostly — official communications are trusted but employees know some spin is applied$qb$, $qb$Partially — employees routinely cross-check official communications against informal sources$qb$, $qb$No — official communications are routinely disbelieved$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q01$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$L+MM+E$qb$, $qb$Management behaviour in your organisation under pressure (tight deadlines, budget cuts, poor results) compared to normal conditions is:$qb$, $qb$Consistent — standards, respect, and communication quality are maintained regardless of pressure$qb$, $qb$Mostly consistent — some fraying under extreme pressure but generally stable$qb$, $qb$Noticeably different — pressure reveals a significantly different management style$qb$, $qb$Dramatically different — managers under pressure behave in ways that damage trust and morale$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q02$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation can predict how their manager will respond to a given situation:$qb$, $qb$Yes — management behaviour is consistent and predictable; employees rarely feel blindsided$qb$, $qb$Mostly — behaviour is predictable in routine situations but less so under stress or ambiguity$qb$, $qb$Partially — management responses vary enough that employees feel uncertain$qb$, $qb$No — management unpredictability is a source of significant employee anxiety$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q03$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$Rules, policies, and standards in your organisation are applied:$qb$, $qb$Consistently — the same rules apply to everyone regardless of seniority, relationships, or function$qb$, $qb$Generally consistently — occasional exceptions are made but are not the dominant pattern$qb$, $qb$Inconsistently — different standards clearly apply to different people or teams$qb$, $qb$Selectively — policy is used as a tool of control rather than applied impartially$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q04$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$L+MM+E$qb$, $qb$Promises made by management during hiring, onboarding, or role changes in your organisation are:$qb$, $qb$Kept — what is promised is delivered; employees can rely on management commitments made at key transitions$qb$, $qb$Mostly kept — significant promises are honoured; smaller ones sometimes slip$qb$, $qb$Partially kept — there is a pattern of over-promising and under-delivering$qb$, $qb$Routinely broken — employees have learned not to take management promises at face value$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q05$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$MM+E$qb$, $qb$When management changes direction (strategy, policy, priority) in your organisation, employees experience:$qb$, $qb$Clarity — the reason for the change is explained, the old direction is formally closed, and the new one is clearly set$qb$, $qb$Announcement — the change is communicated but the rationale is incomplete$qb$, $qb$Confusion — direction changes happen without sufficient explanation$qb$, $qb$Whiplash — frequent and unexplained direction changes have eroded employee trust in management$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q06$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$L+MM$qb$, $qb$Management positions on important topics (compensation, culture, growth, performance) in your organisation:$qb$, $qb$Are consistent over time — positions change only when there is a clear and communicated reason$qb$, $qb$Are generally stable — some inconsistency exists but it does not undermine trust$qb$, $qb$Shift frequently — employees are uncertain what management actually believes on key topics$qb$, $qb$Are unpredictable — management positions change based on audience, mood, or political convenience$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q07$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$E$qb$, $qb$The management behaviour employees experience in your organisation matches the culture described in onboarding, employer branding, and internal communications:$qb$, $qb$Closely — what is promised about the culture is largely what employees experience$qb$, $qb$Partially — some aspects match; others are noticeably aspirational$qb$, $qb$Poorly — significant gaps exist between the described and the experienced culture$qb$, $qb$Not at all — what is promised and what is experienced are fundamentally different$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q08$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$L+MM+E$qb$, $qb$When the same type of performance issue or conduct issue occurs in different parts of the organisation, the management response is:$qb$, $qb$Consistent — the same standards and processes are applied regardless of which team or individual is involved$qb$, $qb$Generally consistent — some variation exists but the overall standard is maintained$qb$, $qb$Inconsistent — similar issues are treated very differently depending on who is involved$qb$, $qb$Arbitrary — management response to issues is determined by relationships and politics, not policy$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q09$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$MM$qb$, $qb$Middle managers in your organisation receive consistent direction from senior leadership:$qb$, $qb$Yes — direction is aligned across senior leaders; middle managers do not receive conflicting instructions$qb$, $qb$Mostly — occasional mixed signals exist but the overall direction is clear$qb$, $qb$Inconsistently — middle managers regularly receive conflicting direction from different senior leaders$qb$, $qb$No — inconsistent direction from senior leaders is a major source of organisational confusion$qb$, 5, 3, 2, 1, true),
  ($qb$S02C02Q10$qb$, $qb$S02$qb$, $qb$C02$qb$, $qb$L+MM+E$qb$, $qb$Standards of conduct expected of employees in your organisation are:$qb$, $qb$Clear, documented, and consistently enforced at all levels$qb$, $qb$Clear and generally enforced — occasional inconsistencies exist$qb$, $qb$Documented but inconsistently enforced — standards are known but application varies$qb$, $qb$Unclear or unenforced — expected conduct standards are ambiguous or ignored$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q01$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$L+MM+E$qb$, $qb$Promotion and advancement decisions in your organisation are made primarily on:$qb$, $qb$Performance, capability, and potential — with a transparent process that employees understand and trust$qb$, $qb$Primarily merit — though relationships and visibility play a supporting role$qb$, $qb$A mix of merit and relationships — who you know matters as much as what you deliver$qb$, $qb$Relationships and politics — merit is secondary to proximity to power$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q02$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$MM+E$qb$, $qb$Employees from different backgrounds, genders, or tenures in your organisation are treated with equal fairness by management:$qb$, $qb$Yes — fairness across all groups is a visible and enforced management standard$qb$, $qb$Mostly — unintentional bias exists but is not systematic$qb$, $qb$Partially — some groups are visibly treated differently$qb$, $qb$No — differential treatment of different groups is a known and unaddressed issue$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q03$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$L+MM$qb$, $qb$Salary, bonus, and reward decisions in your organisation are:$qb$, $qb$Based on defined criteria that employees understand — process is transparent and outcomes feel fair$qb$, $qb$Guided by criteria but with significant manager discretion — some feel the process is fair, others don't$qb$, $qb$Opaque — criteria are not well communicated and outcomes feel arbitrary to many employees$qb$, $qb$Arbitrary — reward decisions are driven by favouritism and are a known source of resentment$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q04$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$MM+E$qb$, $qb$When two employees with similar performance records are treated differently in your organisation, it is typically because:$qb$, $qb$There is a legitimate and explainable difference in role, context, or documented performance distinction$qb$, $qb$There are sometimes legitimate reasons but not always — inconsistency is acknowledged$qb$, $qb$It is hard to explain — differential treatment is visible but not justified$qb$, $qb$Favouritism — differential treatment in this organisation is driven by relationships, not performance$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q05$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$E$qb$, $qb$Employees in your organisation who raise grievances or complaints about unfair treatment receive:$qb$, $qb$A fair and timely process — grievances are investigated impartially and outcomes are communicated$qb$, $qb$An adequate process — complaints are taken seriously but the process is slow or imperfect$qb$, $qb$A perfunctory response — grievances are handled in ways that protect the organisation rather than ensure fairness$qb$, $qb$Retaliation risk — raising a grievance is known to damage the employee's standing$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q06$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$L+MM+E$qb$, $qb$Access to development opportunities, high-profile projects, and senior exposure in your organisation is:$qb$, $qb$Based on merit and potential — visible and accessible to employees who demonstrate capability$qb$, $qb$Partly merit-based — some opportunities are allocated fairly; others go to the usual suspects$qb$, $qb$Network-dependent — access is primarily determined by relationships with decision-makers$qb$, $qb$Controlled — access to opportunity is a tool of management power, not development$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q07$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$MM$qb$, $qb$Recognition and praise from managers in your organisation is distributed:$qb$, $qb$Fairly — managers recognise contribution across their team, not just high-visibility or favoured individuals$qb$, $qb$Mostly fairly — some individuals get more recognition than their contribution warrants$qb$, $qb$Unevenly — the same people are recognised repeatedly while others feel invisible$qb$, $qb$Very poorly — recognition is explicitly used as a management tool to favour certain individuals$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q08$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$L+MM+E$qb$, $qb$Disciplinary processes in your organisation are applied:$qb$, $qb$Consistently — the same process and standards apply regardless of the individual's seniority or relationships$qb$, $qb$Generally consistently — senior employees face somewhat lighter consequences than junior ones$qb$, $qb$Inconsistently — who you are significantly affects how conduct issues are managed$qb$, $qb$Selectively — discipline is a tool used against disfavoured individuals; favoured ones are protected$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q09$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$L+MM$qb$, $qb$Gender equity in management roles and decision-making in your organisation is:$qb$, $qb$Actively pursued — gender balance is tracked, gaps are identified, and structural changes are made$qb$, $qb$Acknowledged — the gap is recognised and some effort is made but without systematic commitment$qb$, $qb$Discussed but not actioned — gender equity is a stated value without meaningful structural change$qb$, $qb$Not a priority — gender equity in management is not on the organisational agenda$qb$, 5, 3, 2, 1, true),
  ($qb$S02C03Q10$qb$, $qb$S02$qb$, $qb$C03$qb$, $qb$L+MM+E$qb$, $qb$The overall sense of fairness among employees in your organisation — whether the organisation treats people justly — is:$qb$, $qb$Strong — most employees feel the organisation treats them and their colleagues fairly$qb$, $qb$Moderate — fairness is the norm but significant pockets of perceived unfairness exist$qb$, $qb$Weak — a significant portion of employees feel the organisation is not fair to them$qb$, $qb$Very poor — perceived unfairness is a dominant and damaging feature of this organisational culture$qb$, 5, 3, 2, 1, true),
  ($qb$S02C04Q01$qb$, $qb$S02$qb$, $qb$C04$qb$, $qb$MM+E$qb$, $qb$Employees in your organisation respect the professional competence of their immediate manager:$qb$, $qb$Widely — managers are generally seen as more capable than their teams in at least their technical domain$qb$, $qb$Mostly — most managers are respected; some are seen as having been promoted beyond their competence$qb$, $qb$Partially — a significant minority of managers are not respected for their competence$qb$, $qb$Poorly — management competence is a widely acknowledged problem in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S02C04Q02$qb$, $qb$S02$qb$, $qb$C04$qb$, $qb$L+MM$qb$, $qb$Senior leaders in your organisation are credible voices on the industry, market, and future direction of the business:$qb$, $qb$Yes — leadership is widely seen as knowledgeable, well-informed, and capable of navigating the future$qb$, $qb$Mostly — leadership is respected but there are visible gaps in specific areas of expertise$qb$, $qb$Partially — some leaders are credible; others are seen as out of touch with the market$qb$, $qb$No — leadership credibility on business direction is a significant concern$qb$, 5, 3, 2, 1, true),
  ($qb$S02C04Q03$qb$, $qb$S02$qb$, $qb$C04$qb$, $qb$MM+E$qb$, $qb$Managers in your organisation add value to their team beyond administrative oversight — they provide coaching, direction, and professional development:$qb$, $qb$Yes — managers are genuine value-adds who make their teams more effective$qb$, $qb$Some do — management quality varies significantly across the organisation$qb$, $qb$Few — most managers are administrators who coordinate rather than add professional value$qb$, $qb$No — management is widely seen as a bureaucratic layer that slows teams down$qb$, 5, 3, 2, 1, true),
  ($qb$S02C04Q04$qb$, $qb$S02$qb$, $qb$C04$qb$, $qb$L+MM+E$qb$, $qb$When management in your organisation makes a recommendation or decision, employees trust that it is based on sound reasoning:$qb$, $qb$Yes — management decisions are generally well-reasoned and employees trust the process$qb$, $qb$Mostly — some decisions are trusted; others generate scepticism about the reasoning$qb$, $qb$Partially — employees have learned that management decisions are sometimes poorly thought through$qb$, $qb$No — management decision quality is a known and discussed problem in this organisation$qb$, 5, 3, 2, 1, true),
  ($qb$S02C04Q05$qb$, $qb$S02$qb$, $qb$C04$qb$, $qb$MM$qb$, $qb$Managers in your organisation handle team conflict effectively:$qb$, $qb$Yes — conflicts are addressed early, directly, and resolved in ways that preserve team functioning$qb$, $qb$Mostly — managers intervene in serious conflicts but minor ones are often left to fester$qb$, $qb$Rarely — managers avoid conflict; issues are left to escalate$qb$, $qb$No — management inability to handle conflict is a significant and unaddressed organisational problem$qb$, 5, 3, 2, 1, true),
